const list=document.querySelector('[data-project-list]');if(list&&Array.isArray(window.PROJECTS)){const empty=document.querySelector('[data-empty]'),buttons=[...document.querySelectorAll('[data-filter]')];function render(filter='todos'){const items=window.PROJECTS.filter(p=>filter==='todos'||p.category===filter);list.innerHTML=items.map(p=>`<article class="mural-card"><div class="mural-meta"><span>${p.categoryLabel}</span><time>${p.date}</time></div><h2>${p.title}</h2><p>${p.summary}</p><ul class="tech-list">${p.technologies.map(t=>`<li>${t}</li>`).join('')}</ul><div class="learning"><b>Aprendizado / objetivo</b><p>${p.learning}</p></div><footer><span>${p.status}</span><div>${p.demo?`<a href="${p.demo}">Ver projeto ↗</a>`:''}${p.github?`<a href="${p.github}" target="_blank" rel="noopener">GitHub ↗</a>`:''}</div></footer></article>`).join('');empty.hidden=items.length>0}buttons.forEach(button=>button.addEventListener('click',()=>{buttons.forEach(b=>b.classList.remove('active'));button.classList.add('active');render(button.dataset.filter)}));render()}
